import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_alphastar_training_overview.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_actor_learner.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_vtrace.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_self_play_pool.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_driving_league_boundary.png",f=JSON.parse('{"title":"AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成","description":"复杂多智能体任务很难从随机策略开始。AlphaStar 的训练不是单一算法，而是把人类示范、监督学习、异策略强化学习、对手建模和联盟自博弈组合成一条流水线：先用人类对局初始化策略，再让多个智能体在持续变化的对手池中交互，通过价值估计和策略更新提升能力。系统的关键不在“用了强化学习”五个字，而在于数据","frontmatter":{"title":"AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成","description":"复杂多智能体任务很难从随机策略开始。AlphaStar 的训练不是单一算法，而是把人类示范、监督学习、异策略强化学习、对手建模和联盟自博弈组合成一条流水线：先用人类对局初始化策略，再让多个智能体在持续变化的对手池中交互，通过价值估计和策略更新提升能力。系统的关键不在“用了强化学习”五个字，而在于数据","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":8,"source":"2026-08-13/rl_series_29_alphastar_training_league.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_29_alphastar_training_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-29-alphastar-training-league"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成"}],["meta",{"property":"og:description","content":"复杂多智能体任务很难从随机策略开始。AlphaStar 的训练不是单一算法，而是把人类示范、监督学习、异策略强化学习、对手建模和联盟自博弈组合成一条流水线：先用人类对局初始化策略，再让多个智能体在持续变化的对手池中交互，通过价值估计和策略更新提升能力。系统的关键不在“用了强化学习”五个字，而在于数据"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-29-alphastar-training-league"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_alphastar_training_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成"}],["meta",{"name":"twitter:description","content":"复杂多智能体任务很难从随机策略开始。AlphaStar 的训练不是单一算法，而是把人类示范、监督学习、异策略强化学习、对手建模和联盟自博弈组合成一条流水线：先用人类对局初始化策略，再让多个智能体在持续变化的对手池中交互，通过价值估计和策略更新提升能力。系统的关键不在“用了强化学习”五个字，而在于数据"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_29_alphastar_training_overview.png"}]],"prev":{"text":"AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作","link":"/rl/rl-series-28-alphastar-representation-actions"},"next":{"text":"安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来","link":"/rl/rl-series-30-safe-rl-constraints"}},"headers":[],"relativePath":"rl/rl-series-29-alphastar-training-league.md","filePath":"rl/rl-series-29-alphastar-training-league.md","lastUpdated":null}'),p={name:"rl/rl-series-29-alphastar-training-league.md"};function c(d,a,_,u,b,m){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="alphastar-拆解篇二-监督预训练、自博弈与联盟训练如何合成" tabindex="-1">AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成 <a class="header-anchor" href="#alphastar-拆解篇二-监督预训练、自博弈与联盟训练如何合成" aria-label="Permalink to &quot;AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成&quot;">​</a></h1><p>复杂多智能体任务很难从随机策略开始。AlphaStar 的训练不是单一算法，而是把人类示范、监督学习、异策略强化学习、对手建模和联盟自博弈组合成一条流水线：先用人类对局初始化策略，再让多个智能体在持续变化的对手池中交互，通过价值估计和策略更新提升能力。系统的关键不在“用了强化学习”五个字，而在于数据从哪里来、对手如何选择、策略如何避免只学会一种套路。</p><p>本篇承接前一篇的表示和动作结构，重点讲训练机制。AlphaStar 的 Nature 论文报告其在完整 StarCraft II 环境中达到三种种族 Grandmaster（宗师）级别并超过 99.8％ 的官方排名玩家，但这个结果依赖明确的评估条件、工程规模和训练资源。它可以启发复杂系统设计，不能直接证明自动驾驶采用同一架构就会获得同等收益。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-监督学习负责冷启动" tabindex="-1">1.1 监督学习负责冷启动 <a class="header-anchor" href="#_1-1-监督学习负责冷启动" aria-label="Permalink to &quot;1.1 监督学习负责冷启动&quot;">​</a></h3><p>人类回放提供初始策略分布，减少随机探索进入完全无效区域的成本，但也会把人类偏差带入模型。</p><h3 id="_1-2-强化学习负责超越示范" tabindex="-1">1.2 强化学习负责超越示范 <a class="header-anchor" href="#_1-2-强化学习负责超越示范" aria-label="Permalink to &quot;1.2 强化学习负责超越示范&quot;">​</a></h3><p>与环境和对手持续交互，策略可以发现人类数据没有覆盖的战术，但价值估计和分布偏移会让训练更不稳定。</p><h3 id="_1-3-v-trace-处理异步采样偏差" tabindex="-1">1.3 V-trace 处理异步采样偏差 <a class="header-anchor" href="#_1-3-v-trace-处理异步采样偏差" aria-label="Permalink to &quot;1.3 V-trace 处理异步采样偏差&quot;">​</a></h3><p>演员采样策略和学习者当前策略可能不同，需要重要性修正并截断比率，降低异策略更新方差。</p><h3 id="_1-4-联盟训练避免单一对手过拟合" tabindex="-1">1.4 联盟训练避免单一对手过拟合 <a class="header-anchor" href="#_1-4-联盟训练避免单一对手过拟合" aria-label="Permalink to &quot;1.4 联盟训练避免单一对手过拟合&quot;">​</a></h3><p>主智能体、利用者和历史快照形成多样对手池，让策略同时学习利用弱点和防范反制。</p><p><img src="'+l+'" alt="AlphaStar 从示范初始化到联盟训练的总流程"></p><h2 id="二、监督预训练怎样提供初始策略" tabindex="-1">二、监督预训练怎样提供初始策略 <a class="header-anchor" href="#二、监督预训练怎样提供初始策略" aria-label="Permalink to &quot;二、监督预训练怎样提供初始策略&quot;">​</a></h2><h3 id="_2-1-人类回放提供状态—动作序列" tabindex="-1">2.1 人类回放提供状态—动作序列 <a class="header-anchor" href="#_2-1-人类回放提供状态—动作序列" aria-label="Permalink to &quot;2.1 人类回放提供状态—动作序列&quot;">​</a></h3><p>训练样本包含观测、组合动作、时间间隔和对局结果。动作头按前一篇的链式结构分别计算监督损失。</p><h3 id="_2-2-不同动作头使用不同损失" tabindex="-1">2.2 不同动作头使用不同损失 <a class="header-anchor" href="#_2-2-不同动作头使用不同损失" aria-label="Permalink to &quot;2.2 不同动作头使用不同损失&quot;">​</a></h3><p>离散动作类型可用交叉熵，目标点和连续参数可用回归或概率损失。所有头的损失权重需要记录。</p><h3 id="_2-3-监督策略不是最终策略" tabindex="-1">2.3 监督策略不是最终策略 <a class="header-anchor" href="#_2-3-监督策略不是最终策略" aria-label="Permalink to &quot;2.3 监督策略不是最终策略&quot;">​</a></h3><p>它只拟合人类对局分布，在未见对手和反事实状态上可能没有合理行为。预训练完成后仍需独立评估和安全约束。</p><h3 id="_2-4-预训练数据的视野边界必须真实" tabindex="-1">2.4 预训练数据的视野边界必须真实 <a class="header-anchor" href="#_2-4-预训练数据的视野边界必须真实" aria-label="Permalink to &quot;2.4 预训练数据的视野边界必须真实&quot;">​</a></h3><p>训练回放若包含完整地图或未来信息，而在线环境只能看到局部视野，强化学习阶段会出现严重分布断裂。</p><h2 id="三、强化学习阶段怎样更新策略和价值" tabindex="-1">三、强化学习阶段怎样更新策略和价值 <a class="header-anchor" href="#三、强化学习阶段怎样更新策略和价值" aria-label="Permalink to &quot;三、强化学习阶段怎样更新策略和价值&quot;">​</a></h2><h3 id="_3-1-演员与学习者可以异步运行" tabindex="-1">3.1 演员与学习者可以异步运行 <a class="header-anchor" href="#_3-1-演员与学习者可以异步运行" aria-label="Permalink to &quot;3.1 演员与学习者可以异步运行&quot;">​</a></h3><p>多个演员与环境交互生成轨迹，学习者批量更新参数。采样和更新速度不同，产生策略滞后。</p><h3 id="_3-2-价值网络估计状态和动作价值" tabindex="-1">3.2 价值网络估计状态和动作价值 <a class="header-anchor" href="#_3-2-价值网络估计状态和动作价值" aria-label="Permalink to &quot;3.2 价值网络估计状态和动作价值&quot;">​</a></h3><p>评论家提供状态价值、优势或 Q 值，策略用这些估计调整组合动作的对数概率。</p><h3 id="_3-3-优势函数承担动作比较" tabindex="-1">3.3 优势函数承担动作比较 <a class="header-anchor" href="#_3-3-优势函数承担动作比较" aria-label="Permalink to &quot;3.3 优势函数承担动作比较&quot;">​</a></h3><p>$$ A_t=G_t-V(s_t) $$</p><p>其中 (G_t) 是某种回报或自举目标。优势为正时增加动作概率，为负时降低。</p><h3 id="_3-4-价值损失和策略损失必须分开监控" tabindex="-1">3.4 价值损失和策略损失必须分开监控 <a class="header-anchor" href="#_3-4-价值损失和策略损失必须分开监控" aria-label="Permalink to &quot;3.4 价值损失和策略损失必须分开监控&quot;">​</a></h3><p>策略回报上升但价值误差爆炸，或价值损失下降但实际胜率下降，都说明单一训练曲线不足以诊断系统。</p><p><img src="'+h+'" alt="AlphaStar 演员采样、学习者更新与价值估计"></p><h2 id="四、v-trace-怎样处理策略滞后" tabindex="-1">四、V-trace 怎样处理策略滞后 <a class="header-anchor" href="#四、v-trace-怎样处理策略滞后" aria-label="Permalink to &quot;四、V-trace 怎样处理策略滞后&quot;">​</a></h2><h3 id="_4-1-行为策略与目标策略不同" tabindex="-1">4.1 行为策略与目标策略不同 <a class="header-anchor" href="#_4-1-行为策略与目标策略不同" aria-label="Permalink to &quot;4.1 行为策略与目标策略不同&quot;">​</a></h3><p>演员使用 (\\mu) 采样，学习者更新当前策略 (\\pi)。同一动作在两者下的概率不同。</p><h3 id="_4-2-重要性比率修正分布差异" tabindex="-1">4.2 重要性比率修正分布差异 <a class="header-anchor" href="#_4-2-重要性比率修正分布差异" aria-label="Permalink to &quot;4.2 重要性比率修正分布差异&quot;">​</a></h3><p>$$ \\rho_t=\\frac{\\pi(a_t|s_t)}{\\mu(a_t|s_t)} $$</p><p>直接使用比率可能产生极大方差。</p><h3 id="_4-3-截断比率控制异常权重" tabindex="-1">4.3 截断比率控制异常权重 <a class="header-anchor" href="#_4-3-截断比率控制异常权重" aria-label="Permalink to &quot;4.3 截断比率控制异常权重&quot;">​</a></h3><p>V-trace 使用截断的 (\\rho_t) 和 (c_t) 传播价值信息，在偏差和方差之间折中。</p><h3 id="_4-4-截断不等于完全无偏" tabindex="-1">4.4 截断不等于完全无偏 <a class="header-anchor" href="#_4-4-截断不等于完全无偏" aria-label="Permalink to &quot;4.4 截断不等于完全无偏&quot;">​</a></h3><p>它改变了估计目标，换来更稳定的异步训练。实现必须报告截断阈值、策略滞后和演员数量。</p><p><img src="'+o+'" alt="V-trace 用截断重要性比率在偏差与方差之间折中"></p><h2 id="五、为什么需要多智能体和自博弈" tabindex="-1">五、为什么需要多智能体和自博弈 <a class="header-anchor" href="#五、为什么需要多智能体和自博弈" aria-label="Permalink to &quot;五、为什么需要多智能体和自博弈&quot;">​</a></h2><h3 id="_5-1-单一对手会导致策略过拟合" tabindex="-1">5.1 单一对手会导致策略过拟合 <a class="header-anchor" href="#_5-1-单一对手会导致策略过拟合" aria-label="Permalink to &quot;5.1 单一对手会导致策略过拟合&quot;">​</a></h3><p>策略可能只学会击败一个固定对手的套路，换风格就失败。</p><h3 id="_5-2-自博弈提供持续挑战" tabindex="-1">5.2 自博弈提供持续挑战 <a class="header-anchor" href="#_5-2-自博弈提供持续挑战" aria-label="Permalink to &quot;5.2 自博弈提供持续挑战&quot;">​</a></h3><p>自己与自己或历史策略对战，能产生比静态数据更丰富的状态分布。</p><h3 id="_5-3-历史快照保留旧策略" tabindex="-1">5.3 历史快照保留旧策略 <a class="header-anchor" href="#_5-3-历史快照保留旧策略" aria-label="Permalink to &quot;5.3 历史快照保留旧策略&quot;">​</a></h3><p>定期保存策略快照，并从中选择对手，可以防止当前策略遗忘过去的反制能力。</p><h3 id="_5-4-对手池选择影响训练目标" tabindex="-1">5.4 对手池选择影响训练目标 <a class="header-anchor" href="#_5-4-对手池选择影响训练目标" aria-label="Permalink to &quot;5.4 对手池选择影响训练目标&quot;">​</a></h3><p>均匀、按胜率或按难度采样会产生不同学习压力。对手选择器本身也是系统的一部分。</p><p><img src="'+n+'" alt="自博弈历史快照与对手池"></p><h2 id="六、联盟训练如何避免策略循环" tabindex="-1">六、联盟训练如何避免策略循环 <a class="header-anchor" href="#六、联盟训练如何避免策略循环" aria-label="Permalink to &quot;六、联盟训练如何避免策略循环&quot;">​</a></h2><h3 id="_6-1-主智能体追求总体能力" tabindex="-1">6.1 主智能体追求总体能力 <a class="header-anchor" href="#_6-1-主智能体追求总体能力" aria-label="Permalink to &quot;6.1 主智能体追求总体能力&quot;">​</a></h3><p>主智能体在多种对手上训练，目标是提高通用胜率和策略鲁棒性。</p><h3 id="_6-2-联盟利用者专门寻找弱点" tabindex="-1">6.2 联盟利用者专门寻找弱点 <a class="header-anchor" href="#_6-2-联盟利用者专门寻找弱点" aria-label="Permalink to &quot;6.2 联盟利用者专门寻找弱点&quot;">​</a></h3><p>利用者尝试击败主智能体或联盟中的策略，迫使主智能体补齐漏洞。</p><h3 id="_6-3-主利用者验证整体弱点" tabindex="-1">6.3 主利用者验证整体弱点 <a class="header-anchor" href="#_6-3-主利用者验证整体弱点" aria-label="Permalink to &quot;6.3 主利用者验证整体弱点&quot;">​</a></h3><p>主利用者持续针对多个主智能体训练，用于发现联盟共同的脆弱模式。</p><h3 id="_6-4-重置机制维持多样性" tabindex="-1">6.4 重置机制维持多样性 <a class="header-anchor" href="#_6-4-重置机制维持多样性" aria-label="Permalink to &quot;6.4 重置机制维持多样性&quot;">​</a></h3><p>利用者可周期性重置到监督初始化，避免所有策略收敛到同一个局部套路。</p><h2 id="七、自动驾驶中如何借鉴联盟思想" tabindex="-1">七、自动驾驶中如何借鉴联盟思想 <a class="header-anchor" href="#七、自动驾驶中如何借鉴联盟思想" aria-label="Permalink to &quot;七、自动驾驶中如何借鉴联盟思想&quot;">​</a></h2><h3 id="_7-1-对手可以是交通场景策略" tabindex="-1">7.1 对手可以是交通场景策略 <a class="header-anchor" href="#_7-1-对手可以是交通场景策略" aria-label="Permalink to &quot;7.1 对手可以是交通场景策略&quot;">​</a></h3><p>跟车、加塞、行人横穿和恶劣天气生成器可以形成多样化环境对手，但必须限定在真实可行分布。</p><h3 id="_7-2-不应把危险对手直接放到实车" tabindex="-1">7.2 不应把危险对手直接放到实车 <a class="header-anchor" href="#_7-2-不应把危险对手直接放到实车" aria-label="Permalink to &quot;7.2 不应把危险对手直接放到实车&quot;">​</a></h3><p>高风险交互应在仿真、封闭场地或安全屏障下进行。自博弈不是取消安全审查的理由。</p><h3 id="_7-3-场景快照需要版本化" tabindex="-1">7.3 场景快照需要版本化 <a class="header-anchor" href="#_7-3-场景快照需要版本化" aria-label="Permalink to &quot;7.3 场景快照需要版本化&quot;">​</a></h3><p>记录场景生成器、地图、动力学、交通参与者策略和随机种子，才能复现对手池。</p><p><img src="'+s+'" alt="自动驾驶多场景对手池与安全评估"></p><h2 id="八、一个最小实验怎样设计" tabindex="-1">八、一个最小实验怎样设计 <a class="header-anchor" href="#八、一个最小实验怎样设计" aria-label="Permalink to &quot;八、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_8-1-用简化双智能体环境开始" tabindex="-1">8.1 用简化双智能体环境开始 <a class="header-anchor" href="#_8-1-用简化双智能体环境开始" aria-label="Permalink to &quot;8.1 用简化双智能体环境开始&quot;">​</a></h3><p>选择有策略反制的网格对战或车道交互任务，先验证单一对手、历史快照和利用者的差异。</p><h3 id="_8-2-比较静态对手与联盟对手" tabindex="-1">8.2 比较静态对手与联盟对手 <a class="header-anchor" href="#_8-2-比较静态对手与联盟对手" aria-label="Permalink to &quot;8.2 比较静态对手与联盟对手&quot;">​</a></h3><p>统一环境步和计算预算，比较对手泛化、反制速度、策略多样性和最差表现。</p><h3 id="_8-3-做监督初始化消融" tabindex="-1">8.3 做监督初始化消融 <a class="header-anchor" href="#_8-3-做监督初始化消融" aria-label="Permalink to &quot;8.3 做监督初始化消融&quot;">​</a></h3><p>比较随机初始化和示范初始化，记录首次有效学习时间与最终超越示范的幅度。</p><h3 id="_8-4-报告评估对手分布" tabindex="-1">8.4 报告评估对手分布 <a class="header-anchor" href="#_8-4-报告评估对手分布" aria-label="Permalink to &quot;8.4 报告评估对手分布&quot;">​</a></h3><p>不能只在训练对手上测试。应保留未见策略、长尾场景和固定基准对手。</p><h2 id="九、最常见的实现错误" tabindex="-1">九、最常见的实现错误 <a class="header-anchor" href="#九、最常见的实现错误" aria-label="Permalink to &quot;九、最常见的实现错误&quot;">​</a></h2><h3 id="_9-1-把自博弈胜率当成绝对能力" tabindex="-1">9.1 把自博弈胜率当成绝对能力 <a class="header-anchor" href="#_9-1-把自博弈胜率当成绝对能力" aria-label="Permalink to &quot;9.1 把自博弈胜率当成绝对能力&quot;">​</a></h3><p>策略可能只是在当前循环中互相适应，离开联盟就崩溃。</p><h3 id="_9-2-忽略策略滞后" tabindex="-1">9.2 忽略策略滞后 <a class="header-anchor" href="#_9-2-忽略策略滞后" aria-label="Permalink to &quot;9.2 忽略策略滞后&quot;">​</a></h3><p>异步演员数据必须携带行为策略版本或可重建概率，否则 V-trace 修正无法正确计算。</p><h3 id="_9-3-对手池没有历史保留" tabindex="-1">9.3 对手池没有历史保留 <a class="header-anchor" href="#_9-3-对手池没有历史保留" aria-label="Permalink to &quot;9.3 对手池没有历史保留&quot;">​</a></h3><p>只与最新策略交互会产生遗忘和循环克制。</p><h3 id="_9-4-用不受限动作比较系统" tabindex="-1">9.4 用不受限动作比较系统 <a class="header-anchor" href="#_9-4-用不受限动作比较系统" aria-label="Permalink to &quot;9.4 用不受限动作比较系统&quot;">​</a></h3><p>若训练允许更高动作频率、全图视野或不公平接口，评价不能与人类或真实系统直接比较。</p><h2 id="十、学到什么程度才算掌握" tabindex="-1">十、学到什么程度才算掌握 <a class="header-anchor" href="#十、学到什么程度才算掌握" aria-label="Permalink to &quot;十、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_10-1-能画出完整训练流水线" tabindex="-1">10.1 能画出完整训练流水线 <a class="header-anchor" href="#_10-1-能画出完整训练流水线" aria-label="Permalink to &quot;10.1 能画出完整训练流水线&quot;">​</a></h3><p>你应能标出监督数据、演员、学习者、价值网络、V-trace 和联盟对手池。</p><h3 id="_10-2-能解释自博弈的多样性价值" tabindex="-1">10.2 能解释自博弈的多样性价值 <a class="header-anchor" href="#_10-2-能解释自博弈的多样性价值" aria-label="Permalink to &quot;10.2 能解释自博弈的多样性价值&quot;">​</a></h3><p>你应能说明历史快照和利用者如何减少单一对手过拟合。</p><h3 id="_10-3-能设计公平评价" tabindex="-1">10.3 能设计公平评价 <a class="header-anchor" href="#_10-3-能设计公平评价" aria-label="Permalink to &quot;10.3 能设计公平评价&quot;">​</a></h3><p>你应能报告约束、对手分布、资源预算、随机种子和未见场景。</p><h3 id="_10-4-能进入安全强化学习" tabindex="-1">10.4 能进入安全强化学习 <a class="header-anchor" href="#_10-4-能进入安全强化学习" aria-label="Permalink to &quot;10.4 能进入安全强化学习&quot;">​</a></h3><p>下一篇将把“奖励最大化”改写成“奖励与约束同时满足”。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://www.nature.com/articles/s41586-019-1724-z" target="_blank" rel="noreferrer">Vinyals 等《Grandmaster level in StarCraft II using multi-agent reinforcement learning》</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter13/chapter13.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十三章 AlphaStar 论文解读</a></p><p><a href="https://arxiv.org/abs/1802.01561" target="_blank" rel="noreferrer">Espeholt 等《IMPALA: Scalable Distributed Deep-RL with Importance Weighted Actor-Learner Architectures》</a></p><p><a href="https://deepmind.google/blog/alphastar-grandmaster-level-in-starcraft-ii-using-multi-agent-reinforcement-learning/" target="_blank" rel="noreferrer">DeepMind AlphaStar 项目介绍</a></p>',103)])])}const g=e(p,[["render",c]]);export{f as __pageData,g as default};
